//! RAR archives made by rar.exe, committed as fixtures (`fixtures/rar*`, regenerated by
//! `fixtures/make-rar-fixtures.sh`). These run without WinRAR installed.

use super::tests_sevenz::tree_files;
use super::*;
use forge_jobs::{CancelToken, Progress};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("src/archive/fixtures")
        .join(name)
}

/// The tree the archives were made from (see `make-rar-fixtures.sh`), files only.
fn expected_files() -> Vec<(String, Vec<u8>)> {
    let mut files = vec![
        (
            "src/hello.txt".to_owned(),
            "hello rar\n".repeat(200).into_bytes(),
        ),
        (
            "src/sub/data.bin".to_owned(),
            (0..4096u32).map(|i| ((i * 31) % 256) as u8).collect(),
        ),
        ("src/zero.txt".to_owned(), Vec::new()),
        ("src/Проект.txt".to_owned(), b"unicode name\n".to_vec()),
    ];
    files.sort();
    files
}

fn extract_with(name: &str, password: Option<&str>) -> (tempfile::TempDir, Result<ExtractReport>) {
    let d = tempfile::tempdir().unwrap();
    let (c, p) = (CancelToken::new(), Progress::default());
    let ctx = JobCtx::new(&c, &p);
    let opts = ExtractOptions {
        password: password.map(Password::new),
        ..Default::default()
    };
    let r = extract(&fixture(name), d.path(), &opts, None, &ctx);
    (d, r)
}

fn test_with(path: &Path, password: Option<&str>) -> Result<TestReport> {
    let (c, p) = (CancelToken::new(), Progress::default());
    let ctx = JobCtx::new(&c, &p);
    test_archive(
        path,
        password.map(Password::new).as_ref(),
        &ExtractLimits::default(),
        &ctx,
    )
}

#[test]
fn rar_fixtures_extract_exactly() {
    let cases = [
        ("rar5.rar", None),
        ("rar4.rar", None),
        ("rar5-solid.rar", None),
        ("rar4-solid.rar", None),
        ("rar5-enc.rar", Some("secret")),
        ("rar4-enc.rar", Some("secret")),
        ("rar5-hdrenc.rar", Some("secret")),
        ("rar4-hdrenc.rar", Some("secret")),
    ];
    for (name, password) in cases {
        let (d, report) = extract_with(name, password);
        let report = report.unwrap_or_else(|e| panic!("{name}: {e:?}"));
        assert!(
            report.failed.is_empty(),
            "{name} failed: {:?}",
            report.failed
        );
        assert!(
            report.skipped.is_empty(),
            "{name} skipped: {:?}",
            report.skipped
        );
        assert!(!report.cancelled, "{name} cancelled");
        assert_eq!(
            tree_files(d.path()),
            expected_files(),
            "{name}: files differ"
        );
        assert!(
            d.path().join("src/empty").is_dir(),
            "{name}: src/empty missing"
        );
        let t = test_with(&fixture(name), password).unwrap_or_else(|e| panic!("{name}: {e:?}"));
        assert!(t.is_ok(), "{name}: test failed: {:?}", t.entries);
        assert_eq!(t.entries.len(), 4, "{name}: {:?}", t.entries);
    }
}

#[test]
fn rar_is_detected_by_content_and_name() {
    let d = tempfile::tempdir().unwrap();
    let renamed = d.path().join("looks-like.zip");
    fs::copy(fixture("rar5.rar"), &renamed).unwrap();
    assert_eq!(
        backend_for_file(&renamed).unwrap().format(),
        ArchiveFormat::Rar
    );
    let renamed4 = d.path().join("old.dat");
    fs::copy(fixture("rar4.rar"), &renamed4).unwrap();
    assert_eq!(
        backend_for_file(&renamed4).unwrap().format(),
        ArchiveFormat::Rar
    );
    assert!(is_archive_name(Path::new("x.rar")));
    assert!(is_archive_name(Path::new("x.R07")));
    assert!(is_archive_name(Path::new("x.part2.rar")));
    let listing = list(&renamed).unwrap();
    assert_eq!(listing.format, ArchiveFormat::Rar);
}

#[test]
fn rar_listing_reports_methods_solid_and_checksums() {
    let l = list(&fixture("rar5.rar")).unwrap();
    let hello = l
        .entries
        .iter()
        .find(|e| e.name == "src/hello.txt")
        .unwrap();
    assert_eq!(hello.size, 2000);
    assert!(hello.method.starts_with("RAR5"), "{}", hello.method);
    assert!(hello.modified.is_some());
    assert!(!hello.solid && !hello.unchecked && hello.safe_name);
    let dir = l.entries.iter().find(|e| e.name == "src/empty/").unwrap();
    assert!(dir.is_dir);

    let l4 = list(&fixture("rar4.rar")).unwrap();
    let hello4 = l4
        .entries
        .iter()
        .find(|e| e.name == "src/hello.txt")
        .unwrap();
    assert!(hello4.method.starts_with("RAR4"), "{}", hello4.method);
    assert_eq!(
        hello4.crc32,
        crc32fast::hash(&"hello rar\n".repeat(200).into_bytes())
    );

    let solid = list(&fixture("rar5-solid.rar")).unwrap();
    let files: Vec<_> = solid.entries.iter().filter(|e| !e.is_dir).collect();
    assert!(files.iter().filter(|e| e.solid).count() >= 2, "{files:?}");
}

#[test]
fn rar_encrypted_files_need_the_right_password() {
    for name in ["rar5-enc.rar", "rar4-enc.rar"] {
        let l = list(&fixture(name)).unwrap();
        assert!(l.any_encrypted(), "{name}");
        let (d, r) = extract_with(name, None);
        assert!(
            matches!(r, Err(CoreError::PasswordRequired(_))),
            "{name}: {r:?}"
        );
        let (_, r) = extract_with(name, Some("wrong"));
        assert!(
            matches!(r, Err(CoreError::WrongPassword(_))),
            "{name}: {r:?}"
        );
        assert!(tree_files(d.path()).is_empty(), "{name}: wrote files");
    }
    let enc5 = list(&fixture("rar5-enc.rar")).unwrap();
    assert!(
        enc5.entries
            .iter()
            .any(|e| e.encryption == Some(EntryEncryption::RarAes))
    );
    let enc4 = list(&fixture("rar4-enc.rar")).unwrap();
    assert!(
        enc4.entries
            .iter()
            .any(|e| e.encryption == Some(EntryEncryption::Rar4Aes))
    );
}

#[test]
fn rar_encrypted_headers_need_the_password_to_list() {
    for name in ["rar5-hdrenc.rar", "rar4-hdrenc.rar"] {
        let r = list(&fixture(name));
        assert!(
            matches!(r, Err(CoreError::PasswordRequired(_))),
            "{name}: {r:?}"
        );
        let r = list_with_password(&fixture(name), Some(&Password::new("wrong")));
        assert!(
            matches!(r, Err(CoreError::WrongPassword(_))),
            "{name}: {r:?}"
        );
        let l = list_with_password(&fixture(name), Some(&Password::new("secret"))).unwrap();
        assert_eq!(l.entries.iter().filter(|e| !e.is_dir).count(), 4, "{name}");
    }
}

#[test]
fn rar_volume_sets_open_from_any_volume() {
    for name in [
        "rar5-vol.part1.rar",
        "rar5-vol.part3.rar",
        "rar4-vol.rar",
        "rar4-vol.r01",
    ] {
        let l = list(&fixture(name)).unwrap_or_else(|e| panic!("{name}: {e:?}"));
        let big = l.entries.iter().find(|e| e.name == "src/big.bin").unwrap();
        assert_eq!(big.size, 24576, "{name}");
        // Split over the volumes: its packed size is all of its parts.
        assert!(big.compressed_size >= 24576, "{name}: {big:?}");
        let d = tempfile::tempdir().unwrap();
        let (c, p) = (CancelToken::new(), Progress::default());
        let report = extract(
            &fixture(name),
            d.path(),
            &ExtractOptions::default(),
            None,
            &JobCtx::new(&c, &p),
        )
        .unwrap_or_else(|e| panic!("{name}: {e:?}"));
        assert!(report.failed.is_empty(), "{name}: {:?}", report.failed);
        let files = tree_files(d.path());
        let big = files.iter().find(|(n, _)| n == "src/big.bin").unwrap();
        assert_eq!(big.1.len(), 24576, "{name}");
        let t = test_with(&fixture(name), None).unwrap();
        assert!(t.is_ok(), "{name}: {:?}", t.entries);
    }
}

#[test]
fn rar_missing_volumes_are_named() {
    let d = tempfile::tempdir().unwrap();
    for part in [
        "rar5-vol.part1.rar",
        "rar5-vol.part2.rar",
        "rar5-vol.part4.rar",
    ] {
        fs::copy(fixture(part), d.path().join(part)).unwrap();
    }
    let e = list(&d.path().join("rar5-vol.part1.rar")).unwrap_err();
    let text = e.to_string();
    assert!(text.contains("missing"), "{text}");

    // A later volume without the first one.
    let d2 = tempfile::tempdir().unwrap();
    fs::copy(
        fixture("rar5-vol.part2.rar"),
        d2.path().join("rar5-vol.part2.rar"),
    )
    .unwrap();
    let e = list(&d2.path().join("rar5-vol.part2.rar"))
        .unwrap_err()
        .to_string();
    assert!(
        e.contains("rar5-vol.part1.rar") && e.contains("first volume"),
        "{e}"
    );

    let d3 = tempfile::tempdir().unwrap();
    for part in ["rar4-vol.rar", "rar4-vol.r00", "rar4-vol.r02"] {
        fs::copy(fixture(part), d3.path().join(part)).unwrap();
    }
    let e = list(&d3.path().join("rar4-vol.rar"))
        .unwrap_err()
        .to_string();
    assert!(e.contains("missing"), "{e}");
}

#[test]
fn rar_bad_checksum_publishes_nothing_and_test_reports_it() {
    let (d, r) = extract_with("rar5-badcrc.rar", None);
    let report = r.unwrap();
    assert_eq!(report.failed.len(), 1, "{report:?}");
    assert!(report.extracted.is_empty(), "{report:?}");
    assert!(
        tree_files(d.path()).is_empty(),
        "a damaged file was published"
    );
    let t = test_with(&fixture("rar5-badcrc.rar"), None).unwrap();
    assert!(!t.is_ok());
    assert_eq!(t.failures().count(), 1, "{:?}", t.entries);
}

#[test]
fn rar_unsafe_names_refuse_extraction() {
    let l = list(&fixture("rar5-unsafe.rar")).unwrap();
    // UnRAR itself blanks a name with `..` in it (and turns `:` into `_`): never safe.
    let evil = &l.entries[0];
    assert_ne!(evil.name, "../evil.txt", "{evil:?}");
    assert!(!evil.safe_name, "{evil:?}");
    assert_eq!(ArchiveIndex::build(l.clone()).unsafe_entries, 1);
    let (d, r) = extract_with("rar5-unsafe.rar", None);
    assert!(matches!(r, Err(CoreError::UnsafePath(_))), "{r:?}");
    assert!(tree_files(d.path()).is_empty());
    assert!(!d.path().parent().unwrap().join("evil.txt").exists());
}

#[test]
fn rar_large_dictionary_is_refused_before_decoding() {
    let l = list(&fixture("rar5-bigdict.rar")).unwrap();
    assert_eq!(l.entries.len(), 1);
    let (d, r) = extract_with("rar5-bigdict.rar", None);
    let e = r.unwrap_err();
    assert!(matches!(e, CoreError::UnsafePath(_)), "{e:?}");
    assert!(e.to_string().contains("2048 MiB"), "{e}");
    assert!(tree_files(d.path()).is_empty());
    assert!(test_with(&fixture("rar5-bigdict.rar"), None).is_err());
}

#[test]
fn rar_hard_links_are_skipped() {
    let (d, r) = extract_with("rar5-hardlink.rar", None);
    let report = r.unwrap();
    assert_eq!(report.skipped.len(), 1, "{report:?}");
    assert!(report.failed.is_empty(), "{report:?}");
    assert_eq!(
        tree_files(d.path()),
        vec![("target.txt".to_owned(), b"target\n".to_vec())]
    );
}

#[test]
fn rar_selection_from_a_solid_archive() {
    for name in ["rar5-solid.rar", "rar4-solid.rar"] {
        let d = tempfile::tempdir().unwrap();
        let (c, p) = (CancelToken::new(), Progress::default());
        let sel = Selection::new("src/", vec!["src/zero.txt".into(), "src/Проект.txt".into()]);
        let report = extract(
            &fixture(name),
            d.path(),
            &ExtractOptions::default(),
            Some(&sel),
            &JobCtx::new(&c, &p),
        )
        .unwrap();
        assert!(report.failed.is_empty(), "{name}: {:?}", report.failed);
        assert_eq!(
            tree_files(d.path()),
            vec![
                ("zero.txt".to_owned(), Vec::new()),
                ("Проект.txt".to_owned(), b"unicode name\n".to_vec()),
            ],
            "{name}"
        );
    }
}

#[test]
fn rar_cancelled_extraction_publishes_nothing() {
    let d = tempfile::tempdir().unwrap();
    let (c, p) = (CancelToken::new(), Progress::default());
    c.cancel();
    let r = extract(
        &fixture("rar5.rar"),
        d.path(),
        &ExtractOptions::default(),
        None,
        &JobCtx::new(&c, &p),
    );
    match r {
        Ok(report) => assert!(report.cancelled, "{report:?}"),
        Err(e) => assert!(matches!(e, CoreError::Cancelled), "{e:?}"),
    }
    assert!(tree_files(d.path()).is_empty());
}

#[test]
fn rar_is_never_written() {
    let d = tempfile::tempdir().unwrap();
    let (c, p) = (CancelToken::new(), Progress::default());
    let ctx = JobCtx::new(&c, &p);
    let src = d.path().join("a.txt");
    fs::write(&src, b"x").unwrap();
    let e = create(
        std::slice::from_ref(&src),
        &d.path().join("new.rar"),
        &CreateOptions::default(),
        &ctx,
    )
    .unwrap_err();
    assert!(e.to_string().contains(RAR_READ_ONLY), "{e}");
    assert!(!d.path().join("new.rar").exists());
    let copy = d.path().join("copy.rar");
    fs::copy(fixture("rar5.rar"), &copy).unwrap();
    let before = fs::read(&copy).unwrap();
    let edit = ArchiveEdit {
        delete: vec!["src/hello.txt".into()],
        ..Default::default()
    };
    let e = update(&copy, &edit, &CreateOptions::default(), &ctx).unwrap_err();
    assert!(e.to_string().contains(RAR_READ_ONLY), "{e}");
    assert_eq!(fs::read(&copy).unwrap(), before);
    assert!(!ArchiveFormat::Rar.can_write());
}

#[test]
fn rar_entry_opens_to_temp() {
    let (c, p) = (CancelToken::new(), Progress::default());
    let path = extract_entry_to_temp(
        &fixture("rar5-solid.rar"),
        "src/sub/data.bin",
        None,
        1 << 20,
        &JobCtx::new(&c, &p),
    )
    .unwrap();
    assert_eq!(fs::read(&path).unwrap().len(), 4096);
}

#[test]
fn rar_first_volume_names() {
    use super::rar_backend::first_volume_name;
    assert_eq!(
        first_volume_name(Path::new(r"C:\d\x.part07.rar")),
        Some(PathBuf::from(r"C:\d\x.part01.rar"))
    );
    assert_eq!(
        first_volume_name(Path::new(r"C:\d\x.part3.rar")),
        Some(PathBuf::from(r"C:\d\x.part1.rar"))
    );
    assert_eq!(
        first_volume_name(Path::new(r"C:\d\x.r12")),
        Some(PathBuf::from(r"C:\d\x.rar"))
    );
    assert_eq!(first_volume_name(Path::new(r"C:\d\x.rar")), None);
}

#[test]
fn rar_files_left_unread_are_skipped_cleanly() {
    // A second extraction finds every file present: nothing is read, the solid stream is
    // still decoded through (and dropped), and each file is reported as skipped.
    for name in ["rar5-solid.rar", "rar5.rar", "rar5-vol.part1.rar"] {
        let d = tempfile::tempdir().unwrap();
        let (c, p) = (CancelToken::new(), Progress::default());
        let ctx = JobCtx::new(&c, &p);
        let first = extract(
            &fixture(name),
            d.path(),
            &ExtractOptions::default(),
            None,
            &ctx,
        )
        .unwrap();
        assert!(first.failed.is_empty(), "{name}: {:?}", first.failed);
        let again = extract(
            &fixture(name),
            d.path(),
            &ExtractOptions::default(),
            None,
            &ctx,
        )
        .unwrap();
        assert!(again.failed.is_empty(), "{name}: {:?}", again.failed);
        assert!(again.extracted.is_empty(), "{name}: {:?}", again.extracted);
        assert_eq!(again.skipped.len(), first.extracted.len(), "{name}");
    }
}

#[test]
fn rar_reads_in_parallel() {
    let handles: Vec<_> = [
        "rar5-solid.rar",
        "rar4.rar",
        "rar5-enc.rar",
        "rar4-solid.rar",
    ]
    .into_iter()
    .map(|name| {
        std::thread::spawn(move || {
            for _ in 0..3 {
                let pw = name.contains("enc").then_some("secret");
                let t = test_with(&fixture(name), pw).unwrap();
                assert!(t.is_ok(), "{name}: {:?}", t.entries);
            }
        })
    })
    .collect();
    for h in handles {
        h.join().unwrap();
    }
}
